<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Control QR de papeleta</title>
<style>body{margin:0;background:#f1f5f9;font-family:Arial,sans-serif;color:#14213d}.wrap{max-width:560px;margin:auto;padding:22px}.card{background:#fff;border-radius:18px;padding:22px;margin:14px 0;box-shadow:0 4px 18px #0001}.notice{color:#075985;background:#e0f2fe}.ok{color:#166534;background:#dcfce7}.error{color:#b91c1c;background:#fee2e2}button{width:100%;padding:15px;border:0;border-radius:12px;background:#075985;color:#fff;font-size:16px;font-weight:bold;cursor:pointer}button.alt{background:#0f766e}button:disabled{opacity:.6;cursor:wait}input{box-sizing:border-box;width:100%;margin:7px 0 13px;padding:12px;border:1px solid #cbd5e1;border-radius:9px;font-size:16px}label{font-weight:bold;font-size:14px}.muted{color:#64748b;font-size:13px;line-height:1.45}.signature-pad{display:block;box-sizing:border-box;border:2px dashed #0f766e;border-radius:12px;width:100%;height:145px;touch-action:none;background:#f8fffc}.inline{display:flex;gap:8px}.inline input{margin-bottom:0}.inline button{width:auto;white-space:nowrap;padding:12px}</style></head>
<body><main class="wrap"><h2>Control de salida</h2><div class="card"><b>Papeleta N.° {{ $papeleta->numero_papeleta }}</b><p>{{ $papeleta->employee?->full_name }} · {{ $papeleta->reason?->nombre }}</p><p>Salida: {{ $papeleta->salida_real_at?->format('d/m/Y H:i') ?? 'Pendiente' }}<br>Retorno: {{ $papeleta->retorno_real_at?->format('d/m/Y H:i') ?? 'Pendiente' }}</p></div>
@if(session('ok'))<div class="card ok">{{ session('ok') }}</div>@endif @if($errors->any())<div class="card error">{{ $errors->first() }}</div>@endif
@if(!$papeleta->salida_real_at)<div class="card notice"><b>Primer paso: salida.</b><br>El responsable de portería debe marcar la salida antes de solicitar la constancia en la entidad destino.</div><form method="post" action="{{ route('papeletas.qr.salida', $token) }}" class="card">@csrf<button>Marcar salida</button></form>
@elseif($papeleta->reason?->tipo === 'comision' && !$papeleta->destino_firmado_at)<div class="card notice"><b>Segundo paso: constancia de destino.</b><br>Valide el DNI, capture el GPS y solicite la firma táctil horizontal.</div><form method="post" action="{{ route('papeletas.qr.destino', $token) }}" class="card" id="destino-form">@csrf<label for="dni">DNI del responsable de destino</label><div class="inline"><input id="dni" name="dni" inputmode="numeric" pattern="[0-9]{8}" maxlength="8" required><button class="alt" type="button" id="buscar-dni">Validar DNI</button></div><p id="dni-status" class="muted">La identidad se valida con el registro institucional o la API configurada.</p><input id="nombre" readonly placeholder="Nombre validado por DNI"><label for="cargo">Cargo del responsable</label><input id="cargo" name="cargo" required maxlength="150"><label>Ubicación GPS de la entidad destino</label><p id="gps-status" class="muted">Toque «Obtener ubicación» y autorice el GPS del teléfono. Se guardarán coordenadas, precisión y fecha/hora.</p><button type="button" class="alt" id="gps-button">Obtener ubicación</button><input type="hidden" id="latitude" name="latitude"><input type="hidden" id="longitude" name="longitude"><input type="hidden" id="accuracy" name="accuracy"><p><label>Firma táctil horizontal</label></p><canvas id="pad" class="signature-pad" aria-label="Firma del responsable"></canvas><input type="hidden" required name="firma" id="firma"><p><button type="submit">Registrar constancia de destino</button></p></form>
@elseif($papeleta->reason?->tipo === 'comision')<div class="card ok">Constancia de destino registrada: {{ $papeleta->destino_firmante_nombre }} · {{ $papeleta->destino_firmante_cargo }}<br>{{ $papeleta->destino_firmado_at->format('d/m/Y H:i') }}</div>@endif
@if($papeleta->salida_real_at && !$papeleta->retorno_real_at && ($papeleta->reason?->tipo !== 'comision' || $papeleta->destino_firmado_at))<form method="post" action="{{ route('papeletas.qr.retorno', $token) }}" class="card">@csrf<button>Marcar retorno</button></form>@endif</main>
@if($papeleta->salida_real_at && $papeleta->reason?->tipo === 'comision' && !$papeleta->destino_firmado_at)<script>(()=>{const f=document.getElementById('destino-form'),dni=document.getElementById('dni'),name=document.getElementById('nombre'),ds=document.getElementById('dni-status'),gs=document.getElementById('gps-status'),gb=document.getElementById('gps-button'),lat=document.getElementById('latitude'),lon=document.getElementById('longitude'),acc=document.getElementById('accuracy'),url=@json(route('papeletas.qr.dni',$token));document.getElementById('buscar-dni').addEventListener('click',async()=>{if(!/^\d{8}$/.test(dni.value)){ds.textContent='Ingrese un DNI de 8 dígitos.';return}ds.textContent='Validando DNI…';name.value='';try{const r=await fetch(`${url}?dni=${encodeURIComponent(dni.value)}`,{headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok||!j.success||!j.data?.nombre_completo)throw new Error(j.message||'No se encontró el DNI.');name.value=j.data.nombre_completo;ds.textContent='Identidad validada.'}catch(e){ds.textContent=e.message||'No se pudo validar el DNI.'}});function gps(){if(!navigator.geolocation){gs.textContent='Este dispositivo no ofrece ubicación GPS.';return}gb.disabled=true;gs.textContent='Solicitando ubicación precisa…';navigator.geolocation.getCurrentPosition(p=>{lat.value=p.coords.latitude.toFixed(7);lon.value=p.coords.longitude.toFixed(7);acc.value=Math.round(p.coords.accuracy);gs.textContent=`Ubicación capturada (precisión aproximada ±${acc.value} m).`;gb.disabled=false},e=>{gb.disabled=false;gs.textContent=`No se pudo obtener el GPS: ${e.message}. Autorice la ubicación y vuelva a intentarlo.`},{enableHighAccuracy:true,timeout:15000,maximumAge:0})}gb.addEventListener('click',gps);const c=document.getElementById('pad'),x=c.getContext('2d');let draw=false,ink=false;function size(){const b=c.getBoundingClientRect(),r=devicePixelRatio||1;c.width=b.width*r;c.height=b.height*r;x.setTransform(r,0,0,r,0,0);x.lineWidth=2.2;x.lineCap='round';x.strokeStyle='#0f172a'}size();function p(e){const b=c.getBoundingClientRect();return{x:e.clientX-b.left,y:e.clientY-b.top}}c.addEventListener('pointerdown',e=>{draw=true;ink=true;c.setPointerCapture(e.pointerId);let q=p(e);x.beginPath();x.moveTo(q.x,q.y);e.preventDefault()});c.addEventListener('pointermove',e=>{if(!draw)return;let q=p(e);x.lineTo(q.x,q.y);x.stroke();e.preventDefault()});['pointerup','pointercancel'].forEach(t=>c.addEventListener(t,()=>draw=false));f.addEventListener('submit',e=>{if(!name.value){e.preventDefault();ds.textContent='Primero valide el DNI del responsable.';return}if(!lat.value||!lon.value){e.preventDefault();gps();return}if(!ink){e.preventDefault();gs.textContent='Solicite la firma táctil horizontal antes de registrar.';return}document.getElementById('firma').value=c.toDataURL('image/png')})})();</script>@endif</body></html>
